            runtimeEventType: event.runtime_event_type || event.runtimeEventType,
            truncateBeforeSeq: ctx.lastUserRuntimeSeq,
            uiRuntimeText: typeof isUiRuntimeFinalText === 'function' && isUiRuntimeFinalText(finalContent),
